nextflow_process {

    name "Test Process MALT_RUN"
    script "../main.nf"
    process "MALT_RUN"
    config './nextflow.config'

    tag "modules"
    tag "modules_nfcore"
    tag "malt"
    tag "malt/run"
    tag "malt/build"

    test("sarscov2 - fastq") {

        def mapping_db
        setup {
            mapping_db = extract('s3://nf-core-test-datasets/modules/data/delete_me/malt/megan-nucl-Feb2022.db.zip')
            run("MALT_BUILD") {
                script "../../../malt/build/main.nf"
                config './nextflow.config'
                process {
                    """
                    input[0] = [
                        [id: "genome"],
                        file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true)
                    ]
                    input[1] = []
                    input[2] = file('${mapping_db}')
                    input[3] = 'mdb'
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test_1', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true)
                    ]
                ]
                input[1] = MALT_BUILD.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                // Alignment order varies between multi-threaded runs, so compare sorted content
                { assert snapshot(
                    path(process.out.alignments[0][1]).linesGzip.sort().join('\n').md5(),
                    sanitizeOutput(process.out, unstableKeys:["rma6", "log", "alignments"])
                ).match() },
                { assert path(process.out.log[0][1]).readLines().last().contains("Peak memory") },
            )
        }

    }

    test("sarscov2 - fastq - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test_1', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true)
                    ]
                ]
                input[1] = [ [id: 'genome'], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

